use Schemastud\DataSchemas\Attributes\Description;
use Schemastud\DataSchemas\Attributes\MapValues;
use Schemastud\DataSchemas\Attributes\Title;
use Splicewire\Beam\Config\Attributes\ConfigKey;
use Splicewire\Beam\Config\Attributes\ConfigRoot;
use Splicewire\Beam\Config\ConfigSection;

/**
 * The `beam.synthetic` Config Section (ADR-0245), generated by `splicewire:beam:make:config-section` from config/beam/synthetic.php.
 *
 * Every key is deploy-only and not overridable until it is opted in.
 */
#[ConfigRoot(root: 'beam.synthetic', title: 'Synthetic data', description: 'How synthetic tenants, blueprints and portfolios are loaded, metered and provisioned for this install.')]
class BeamSyntheticSection extends ConfigSection
{
    public function __construct(
        #[Title('Default usage meter'), Description('The metered name a synthetic blueprint\'s usage is billed against when the blueprint itself names no meter.'), ConfigKey]
        public string $usage_meter,
        #[Title('Blueprint directories'), Description('Directories scanned for blueprint files (.yaml, .yml or .json, one blueprint per file). A relative path resolves against the application base path.'), ConfigKey, ArrayItems('string')]
        public array $blueprint_paths,
        #[Title('Portfolio directories'), Description('Directories scanned for portfolio files, loaded the same way as blueprint directories. Defaults to this package\'s bundled demo portfolio.'), ConfigKey, ArrayItems('string')]
        public array $portfolio_paths,
        #[Title('Load stored portfolios'), Description('Whether portfolios a host saved at runtime (in the shared particles table) are loaded alongside the file-based portfolios.'), ConfigKey]
        public bool $portfolio_store,
        #[Title('Usage units per US dollar'), Description('How many metered usage units one US dollar represents when the host declares no explicit unit cost for the meter.'), ConfigKey]
        public int $usage_units_per_usd,
        #[Title('Provision tenant storage'), Description('Whether synthetic tenant storage (database creation and a scoped migration) is provisioned automatically. Applies only where the host declares no provisioning pipeline of its own.'), ConfigKey]
